import math

def solve_with_pulp():
    try:
        import pulp as pl
    except Exception:
        return None
    prob = pl.LpProblem("GroceryPackages", pl.LpMaximize)
    x = pl.LpVariable("banana_haters", lowBound=0, cat="Integer")
    y = pl.LpVariable("combo", lowBound=0, cat="Integer")
    prob += 6 * x + 7 * y
    prob += 6 * x + 5 * y <= 10
    prob += 6 * y <= 20
    prob += 30 * x + 20 * y <= 80
    status = prob.solve(pl.PULP_CBC_CMD(msg=False))
    if pl.LpStatus[prob.status] != "Optimal":
        return None
    xv = x.value()
    yv = y.value()
    profit = 6 * xv + 7 * yv
    return xv, yv, profit

def solve_with_scipy():
    try:
        import numpy as np
        from scipy.optimize import linprog
    except Exception:
        return None
    c = [-6, -7]
    A = [
        [6, 5],
        [0, 6],
        [30, 20],
    ]
    b = [10, 20, 80]
    bounds = [(0, None), (0, None)]
    res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method="highs")
    if not res.success:
        return None
    x, y = res.x
    def clean(v):
        r = round(v)
        return float(r) if abs(v - r) < 1e-8 else float(v)
    x = clean(x)
    y = clean(y)
    profit = 6 * x + 7 * y
    return x, y, profit

def solve_fallback():
    best = (-1, -1, -1)
    for x in range(0, 100):
        for y in range(0, 100):
            if 6 * x + 5 * y <= 10 and 6 * y <= 20 and 30 * x + 20 * y <= 80:
                profit = 6 * x + 7 * y
                if profit > best[2]:
                    best = (x, y, profit)
    if best[2] >= 0:
        return float(best[0]), float(best[1]), float(best[2])
    return None

def main():
    result = solve_with_pulp()
    if result is None:
        result = solve_with_scipy()
    if result is None:
        result = solve_fallback()
    if result is None:
        print("No solution found")
        return
    x, y, profit = result
    print("banana_haters_packages:", int(round(x)) if abs(x - round(x)) < 1e-8 else x)
    print("combo_packages:", int(round(y)) if abs(y - round(y)) < 1e-8 else y)
    print("max_profit_euros:", profit)

if __name__ == "__main__":
    main()

