import math

def solve_with_scipy():
    try:
        from scipy.optimize import linprog
    except Exception:
        return None
    c = [1.0, 1.0]
    A_ub = [
        [-12.0, -20.0],
        [-15.0, -10.0],
        [30.0, 45.0]
    ]
    b_ub = [-800.0, -1000.0, 5000.0]
    bounds = [(0, None), (0, None)]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return None
    x1, x2 = res.x
    return x1, x2

def solve_with_pulp():
    try:
        import pulp as pl
    except Exception:
        return None
    prob = pl.LpProblem("Minimize_Time", pl.LpMinimize)
    h1 = pl.LpVariable("h1", lowBound=0, cat="Continuous")
    h2 = pl.LpVariable("h2", lowBound=0, cat="Continuous")
    prob += h1 + h2
    prob += 12*h1 + 20*h2 >= 800
    prob += 15*h1 + 10*h2 >= 1000
    prob += 30*h1 + 45*h2 <= 5000
    solver = None
    try:
        solver = pl.PULP_CBC_CMD(msg=False)
    except Exception:
        pass
    prob.solve(solver)
    if pl.LpStatus[prob.status] not in ("Optimal", "Optimal Infeasible"):
        return None
    x1 = pl.value(h1)
    x2 = pl.value(h2)
    return x1, x2

def solve_manually():
    import itertools
    import numpy as np
    def intersect(eq1, eq2):
        A = []
        b = []
        for e in (eq1, eq2):
            if e[0] == "line":
                A.append(e[1])
                b.append(e[2])
            elif e[0] == "x0":
                A.append([1.0, 0.0]); b.append(0.0)
            elif e[0] == "y0":
                A.append([0.0, 1.0]); b.append(0.0)
        A = np.array(A, dtype=float)
        b = np.array(b, dtype=float)
        try:
            sol = np.linalg.solve(A, b)
        except np.linalg.LinAlgError:
            return None
        return float(sol[0]), float(sol[1])

    lines = [
        ("line", [12.0, 20.0], 800.0),
        ("line", [15.0, 10.0], 1000.0),
        ("line", [30.0, 45.0], 5000.0),
        ("x0", None, None),
        ("y0", None, None),
    ]
    candidates = set()
    for a, b in itertools.combinations(range(len(lines)), 2):
        pt = intersect(lines[a], lines[b])
        if pt is not None:
            candidates.add((round(pt[0], 12), round(pt[1], 12)))
    best = None
    for x1, x2 in candidates:
        if x1 is None or x2 is None:
            continue
        if x1 < -1e-9 or x2 < -1e-9:
            continue
        if 12*x1 + 20*x2 + 1e-9 < 800:
            continue
        if 15*x1 + 10*x2 + 1e-9 < 1000:
            continue
        if 30*x1 + 45*x2 - 1e-9 > 5000:
            continue
        val = x1 + x2
        if (best is None) or (val < best[0]):
            best = (val, x1, x2)
    if best is None:
        return None
    return best[1], best[2]

def main():
    sol = solve_with_scipy()
    if sol is None:
        sol = solve_with_pulp()
    if sol is None:
        sol = solve_manually()
    if sol is None:
        print("No solution found")
        return
    h1, h2 = sol
    h1 = 0.0 if abs(h1) < 1e-9 else h1
    h2 = 0.0 if abs(h2) < 1e-9 else h2
    acne = 12*h1 + 20*h2
    anti = 15*h1 + 10*h2
    gel = 30*h1 + 45*h2
    total = h1 + h2
    print("Factory 1 hours:", h1)
    print("Factory 2 hours:", h2)
    print("Total time (hours):", total)
    print("Acne cream produced:", acne)
    print("Anti-bacterial cream produced:", anti)
    print("Base gel used:", gel)

if __name__ == "__main__":
    main()

