import pyomo.environ as pyo
from pyomo.opt import SolverStatus, TerminationCondition

# Build model
model = pyo.ConcreteModel()
model.A = pyo.Var(domain=pyo.NonNegativeIntegers)  # Anxiety medication units
model.D = pyo.Var(domain=pyo.NonNegativeIntegers)  # Anti-depressant units

# Parameters: time per unit (minutes)
model.t_A = pyo.Param(initialize=3)
model.t_D = pyo.Param(initialize=5)

# Total time expression
model.total_effective_time = pyo.Expression(expr=model.t_A * model.A + model.t_D * model.D)

# Constraints
model.c1 = pyo.Constraint(expr=model.A + model.D >= 100)   # At least 100 units total
model.c2 = pyo.Constraint(expr=model.A >= 30)              # At least 30 anxiety medication
model.c3 = pyo.Constraint(expr=model.A <= 2 * model.D)     # At most twice as many A as D

# Objective: minimize total effective time
model.T = pyo.Objective(expr=model.total_effective_time, sense=pyo.minimize)

# Try to find an available MILP solver
solver = None
for name in ['appsi_highs', 'highs', 'cbc', 'glpk']:
    try:
        s = pyo.SolverFactory(name)
        if s is not None and s.available(False):
            solver = s
            break
    except Exception:
        pass

def print_solution(A, D):
    print("A =", int(A))
    print("D =", int(D))
    print("Objective =", int(3 * int(A) + 5 * int(D)))

def fallback_enumeration():
    # Since both times are positive, optimal solution lies on A + D = 100
    best = None
    for D in range(0, 101):
        A = 100 - D
        if A < 30:
            continue
        if A > 2 * D:
            continue
        val = 3 * A + 5 * D
        if best is None or val < best[0]:
            best = (val, A, D)
    if best is None:
        # Very conservative fallback: broaden search a bit just in case
        for A in range(30, 201):
            for D in range(0, 201):
                if A + D < 100:
                    continue
                if A > 2 * D:
                    continue
                val = 3 * A + 5 * D
                if best is None or val < best[0]:
                    best = (val, A, D)
    if best is None:
        raise RuntimeError("No feasible solution found in fallback search.")
    _, A, D = best
    print_solution(A, D)

# Solve with solver if available; otherwise use fallback
if solver is not None:
    try:
        results = solver.solve(model, tee=False)
        if (results.solver.status == SolverStatus.ok and
            results.solver.termination_condition == TerminationCondition.optimal):
            A_val = round(pyo.value(model.A))
            D_val = round(pyo.value(model.D))
            print_solution(A_val, D_val)
        else:
            fallback_enumeration()
    except Exception:
        fallback_enumeration()
else:
    fallback_enumeration()

