import math

def solve_with_pulp():
    from pulp import LpProblem, LpMaximize, LpVariable, LpStatus, value, PULP_CBC_CMD, LpInteger
    prob = LpProblem("Slime_Optimization", LpMaximize)
    x1 = LpVariable('x1', lowBound=0, cat=LpInteger)
    x2 = LpVariable('x2', lowBound=0, cat=LpInteger)
    prob += 4 * x1 + 5 * x2
    prob += 3 * x1 + 8 * x2 <= 100
    prob += 5 * x1 + 6 * x2 <= 90
    prob += 2 * x1 + 4 * x2 <= 30
    prob.solve(PULP_CBC_CMD(msg=False))
    if LpStatus[prob.status] != 'Optimal':
        raise RuntimeError("Non-optimal status")
    return int(value(x1)), int(value(x2)), float(value(prob.objective))

def solve_bruteforce():
    best_val = -1
    best_x1, best_x2 = 0, 0
    max_x1 = min(100 // 3, 90 // 5, 30 // 2)
    max_x2 = min(100 // 8, 90 // 6, 30 // 4)
    for x1 in range(max_x1 + 1):
        for x2 in range(max_x2 + 1):
            if 3 * x1 + 8 * x2 <= 100 and 5 * x1 + 6 * x2 <= 90 and 2 * x1 + 4 * x2 <= 30:
                val = 4 * x1 + 5 * x2
                if val > best_val:
                    best_val = val
                    best_x1, best_x2 = x1, x2
    return best_x1, best_x2, float(best_val)

def main():
    try:
        x1, x2, obj = solve_with_pulp()
    except Exception:
        x1, x2, obj = solve_bruteforce()
    print("Table1_setups:", x1)
    print("Table2_setups:", x2)
    print("Max_slime:", obj)

if __name__ == "__main__":
    main()

