def ceil_div(a, b):
    return -(-a // b)

def solve_min_jars(small_jar_volume=50, large_jar_volume=200, min_ml=100000):
    if large_jar_volume < small_jar_volume:
        raise ValueError("large_jar_volume must be >= small_jar_volume for this solver logic.")

    # Maximum volume achievable with N jars (respecting L <= S) is when L = floor(N/2)
    def max_volume_for_N(N):
        L = N // 2
        return small_jar_volume * N + (large_jar_volume - small_jar_volume) * L

    # Lower bound using even-N capacity: (small + large) * (N/2) >= min_ml  => N >= ceil(2*min_ml/(small+large))
    N = ceil_div(2 * min_ml, small_jar_volume + large_jar_volume)

    # Ensure feasibility considering odd N penalty
    while max_volume_for_N(N) < min_ml:
        N += 1

    # Construct a feasible jar allocation with L <= S that achieves maximal volume for this N
    L = N // 2
    S = N - L

    return S, L, N

if __name__ == "__main__":
    S_val, L_val, obj_val = solve_min_jars(50, 200, 100000)
    print("S:", S_val)
    print("L:", L_val)
    print("Objective:", obj_val)

