    # UB[s] = max over nutrients of ceil(requirement / per_pill_contribution)
    UB = {}
    for s in supplements:
        UB[s] = max(
            ceil(req_iron / iron_per[s]),
            ceil(req_calcium / calcium_per[s])
        )

    best_cost = None
    best_sol = None

    # Optimize by looping over A and computing minimal B needed
    for a in range(0, UB['A'] + 1):
        need_iron = max(0, req_iron - iron_per['A'] * a)
        need_calcium = max(0, req_calcium - calcium_per['A'] * a)

        b_iron = ceil(need_iron / iron_per['B']) if iron_per['B'] > 0 else (0 if need_iron == 0 else float('inf'))
        b_calcium = ceil(need_calcium / calcium_per['B']) if calcium_per['B'] > 0 else (0 if need_calcium == 0 else float('inf'))
        b = max(b_iron, b_calcium)

        if b == float('inf') or b > UB['B']:
            continue

        total_cost = cost['A'] * a + cost['B'] * b
        if best_cost is None or total_cost < best_cost or (total_cost == best_cost and (a + b) < (best_sol['A'] + best_sol['B'])):
            best_cost = total_cost
            best_sol = {'A': a, 'B': b}

