def solve_with_scipy():
    try:
        from scipy.optimize import linprog
        c = [10, 15]
        A_ub = [
            [45, 35],
            [20, 25]
        ]
        b_ub = [900, 800]
        bounds = [(0, None), (0, None)]
        res = linprog(c=c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
        if res.success:
            x, y = res.x
            obj = c[0]*x + c[1]*y
            print("Status: Optimal (scipy)")
            print(f"Optimal original_meals: {x:.6f}")
            print(f"Optimal experimental_meals: {y:.6f}")
            print(f"Minimum total_cooking_time: {obj:.6f}")
            return True
        else:
            return False
    except Exception:
        return False

def solve_by_vertices():
    import itertools
    tol = 1e-9
    cons = [
        (45.0, 35.0, 900.0),
        (20.0, 25.0, 800.0)
    ]
    def feasible(x, y):
        if x < -tol or y < -tol:
            return False
        for a, b, r in cons:
            if a*x + b*y > r + tol:
                return False
        return True
    candidates = [(0.0, 0.0)]
    for a, b, r in cons:
        if a > 0:
            candidates.append((r/a, 0.0))
        if b > 0:
            candidates.append((0.0, r/b))
    eqs = [
        ('c1', cons[0]),
        ('c2', cons[1]),
        ('x0', None),
        ('y0', None)
    ]
    for (n1, d1), (n2, d2) in itertools.combinations(eqs, 2):
        if n1 == 'x0' and n2 == 'y0':
            pt = (0.0, 0.0)
        elif n1 == 'x0' and n2.startswith('c'):
            a, b, r = d2
            if b != 0:
                pt = (0.0, r/b)
            else:
                continue
        elif n1 == 'y0' and n2.startswith('c'):
            a, b, r = d2
            if a != 0:
                pt = (r/a, 0.0)
            else:
                continue
        elif n2 == 'x0' and n1.startswith('c'):
            a, b, r = d1
            if b != 0:
                pt = (0.0, r/b)
            else:
                continue
        elif n2 == 'y0' and n1.startswith('c'):
            a, b, r = d1
            if a != 0:
                pt = (r/a, 0.0)
            else:
                continue
        else:
            a1, b1, r1 = d1
            a2, b2, r2 = d2
            det = a1*b2 - a2*b1
            if abs(det) < tol:
                continue
            x = (r1*b2 - r2*b1) / det
            y = (a1*r2 - a2*r1) / det
            pt = (x, y)
        candidates.append(pt)
    unique = []
    for x, y in candidates:
        found = False
        for ux, uy in unique:
            if abs(x-ux) < 1e-8 and abs(y-uy) < 1e-8:
                found = True
                break
        if not found:
            unique.append((x, y))
    best = None
    best_obj = math.inf
    for x, y in unique:
        if feasible(x, y):
            obj = 10.0*x + 15.0*y
            if obj < best_obj - 1e-9:
                best_obj = obj
                best = (x, y)
    if best is None:
        print("Status: Infeasible")
    else:
        x, y = best
        print("Status: Optimal (vertex enumeration)")
        print(f"Optimal original_meals: {x:.6f}")
        print(f"Optimal experimental_meals: {y:.6f}")
        print(f"Minimum total_cooking_time: {best_obj:.6f}")

